INSERT INTO [dbo].[ISE_ACTIONS] ([Action_Item_Id], [Mat_Question_Id], [Description], [Action_Items], [Regulatory_Citation], [Parent_Id]) VALUES (43, 7746, N'The information security awareness training program is not commensurate to its size, complexity, and risk. Credit unions should train staff to prepare and implement its information security program. The credit union should consider providing specialized training to ensure that personnel sufficiently protect member information in accordance with its information security program.', N'', N'12 C.F.R. § 748.0 (b)(2)', 7655)
INSERT INTO [dbo].[ISE_ACTIONS] ([Action_Item_Id], [Mat_Question_Id], [Description], [Action_Items], [Regulatory_Citation], [Parent_Id]) VALUES (45, 7748, N'The incident response program is not commensurate to its size, complexity, and risk. Each credit union’s information security program should include a response program to address unauthorized access to, or use of, sensitive member information that could result in substantial harm or inconvenience to a member.', N'', N'12 C.F.R. § 748.0 (b)(3)', 7661)
INSERT INTO [dbo].[ISE_ACTIONS] ([Action_Item_Id], [Mat_Question_Id], [Description], [Action_Items], [Regulatory_Citation], [Parent_Id]) VALUES (47, 7750, N'The incident response program is not commensurate to its size, complexity, and risk. Each credit union’s information security program should include a response program to address unauthorized access to, or use of, sensitive member information that could result in substantial harm or inconvenience to a member.', N'', N'12 C.F.R. § 748.0 (b)(3)', 7661)
