INSERT INTO [dbo].[ISE_ACTIONS] ([Action_Item_Id], [Mat_Question_Id], [Description], [Action_Items], [Regulatory_Citation], [Parent_Id]) VALUES (50, 7753, N'The incident response program is not commensurate to its size, complexity, and risk. Each credit union’s information security program should include a response program to address unauthorized access to, or use of, sensitive member information that could result in substantial harm or inconvenience to a member.', N'', N'12 C.F.R. § 748.0 (b)(3)', 7661)
INSERT INTO [dbo].[ISE_ACTIONS] ([Action_Item_Id], [Mat_Question_Id], [Description], [Action_Items], [Regulatory_Citation], [Parent_Id]) VALUES (51, 7759, N'The vendor management program is not sufficient. A financial institution''s board and management should conduct an appropriate due diligence on all potential third parties before selecting and entering into contracts or relationships. The degree of due diligence should be commensurate with the level of risk and complexity of the third-party relationship. Management should maintain a current listing of all third-party service providers. This list should be all-inclusive for services and products offered and vendors utilized.', N'', N'12 C.F.R. § 748.0 (b)(2)', 7669)
INSERT INTO [dbo].[ISE_ACTIONS] ([Action_Item_Id], [Mat_Question_Id], [Description], [Action_Items], [Regulatory_Citation], [Parent_Id]) VALUES (52, 7760, N'The vendor management program is not sufficient. A financial institution''s board and management should conduct an appropriate due diligence on all potential third parties before selecting and entering into contracts or relationships. The degree of due diligence should be commensurate with the level of risk and complexity of the third-party relationship. Management should maintain a current listing of all third-party service providers. This list should be all-inclusive for services and products offered and vendors utilized.', N'', N'12 C.F.R. § 748.0 (b)(2)', 7669)
