INSERT INTO [dbo].[ISE_ACTIONS] ([Action_Item_Id], [Mat_Question_Id], [Description], [Action_Items], [Regulatory_Citation], [Parent_Id]) VALUES (71, 7792, N'Antimalware controls are not sufficient to protect against current sophisticated threats. Malware defenses are used to detect, prevent, or control deployment of malware on credit union assets. Management should ensure an anti-malware solution is deployed on all desktops, laptops, and servers. The solution should have automatic signature updates, and alerts set up for malware detected. All end-point devices should be protected.', N'', N'14 C.F.R. § 748.0 (b)(2)', 7683)
