INSERT INTO [dbo].[ISE_ACTIONS] ([Action_Item_Id], [Mat_Question_Id], [Description], [Action_Items], [Regulatory_Citation], [Parent_Id]) VALUES (104, 7829, N'The network perimeter is not sufficiently protected against external threats.  Perimeter device tools are important defense against unauthorized traffic entering the financial institution''s network.  To control network traffic, the financial institution should use devices such as firewalls to restrict and filter traffic.  Intrusion detection or prevention systems help identify unusual activity by analyzing network traffic and sending alerts or act in blocking traffic that enters the network.', N'', N'20 C.F.R. § 748.0 (b)(2)', 7691)
INSERT INTO [dbo].[ISE_ACTIONS] ([Action_Item_Id], [Mat_Question_Id], [Description], [Action_Items], [Regulatory_Citation], [Parent_Id]) VALUES (106, 7831, N'The email and internet browser controls are not sufficient to detect and prevent threats entering through email and web channels. Email and web browsers are used to interact with external entities and if they are not sufficiently protected can lead to a point of entry for attackers to gain access to a credit union. Each credit union is responsible for deploying controls commensurate with the risk and complexity and protect against threats.', N'', N'13 C.F.R. § 748.0 (b)(2)', 7694)
INSERT INTO [dbo].[ISE_ACTIONS] ([Action_Item_Id], [Mat_Question_Id], [Description], [Action_Items], [Regulatory_Citation], [Parent_Id]) VALUES (108, 7833, N'The email and internet browser controls are not sufficient to detect and prevent threats entering through email and web channels. Email and web browsers are used to interact with external entities and if they are not sufficiently protected can lead to a point of entry for attackers to gain access to a credit union. Each credit union is responsible for deploying controls commensurate with the risk and complexity and protect against threats.', N'', N'15 C.F.R. § 748.0 (b)(2)', 7694)
